import re

import clike as C

FILES = C.files([".rs"], dirs=["src"])
problems = []
text = "\n".join(C.clean(C.read(f), "rust") for f in FILES)
arms = len(re.findall(r'^\s*"[^"\n]*"\s*(?:\|\s*"[^"\n]*"\s*)*=>', text, re.M))
if arms > 7:
    problems.append("%d string-literal match arms remain (at most 7: only Soil::parse should match on strings)" % arms)
if re.search(r'==\s*"', text):
    problems.append("comparison with a string literal found")
m = re.search(r"\benum\s+Soil\s*\{([^}]*)\}", text)
if not m:
    problems.append("missing enum Soil")
else:
    for v in ["Chalk", "Clay", "Peat", "Silt", "Loam"]:
        if not re.search(r"\b" + v + r"\b", m.group(1)):
            problems.append("enum Soil lacks the variant " + v)
C.report(problems)

