//! Allotment watering.

/// The soil types we know about.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Soil {
    Chalk,
Clay,
Peat,
Silt,
Loam,
}

impl Soil {
    /// Parse the lower-case name used in orders; `None` for anything unknown.
    pub fn parse(s: &str) -> Option<Soil> {
        match s {
            "chalk" => Some(Soil::Chalk),
        "clay" => Some(Soil::Clay),
        "peat" => Some(Soil::Peat),
        "silt" => Some(Soil::Silt),
        "loam" => Some(Soil::Loam),
            _ => None,
        }
    }
}

/// Display name of a soil type.
pub fn describe(soil: Soil) -> &'static str {
    match soil {
        Soil::Chalk => "Chalky",
    Soil::Clay => "Heavy clay",
    Soil::Peat => "Peat",
    Soil::Silt => "Silty",
    Soil::Loam => "Loam",
    }
}

/// Whether the bed needs liming.
pub fn needs_lime(soil: Soil) -> bool {
    match soil {
        Soil::Chalk => false,
    Soil::Clay => false,
    Soil::Peat => true,
    Soil::Silt => false,
    Soil::Loam => false,
    }
}

/// Price or amount for a soil type and a quantity (sqm).
pub fn water_litres(soil: Soil, sqm: u32) -> u32 {
    let (base, per) = match soil {
        Soil::Chalk => (65, 30),
    Soil::Clay => (105, 20),
    Soil::Peat => (110, 35),
    Soil::Silt => (90, 15),
    Soil::Loam => (30, 20),
    };
    let qty = sqm;
    base + per * qty / 10
}

/// The string-facing entry point used by order forms.
pub fn water_for(soil: &str, sqm: u32) -> Result<u32, String> {
    let parsed = Soil::parse(soil).ok_or_else(|| format!("unknown soil: {}", soil))?;
    Ok(water_litres(parsed, sqm))
}

