                j += 1
            j = min(n, j + 1)
            out.append(q + "".join("\n" if ch == "\n" else " " for ch in src[i + 1:j - 1]) + (q if j - 1 > i else ""))
            i = j
            prev_sig = q
            continue
        if c == "'" and lang in ("rust", "go"):
            # char literal ('a', '\n', '\u{1F600}') versus lifetime ('a) in rust
            m = re.match(r"'(\\.[^']*|[^\\'])'", src[i:])
