    return "".join(out)


def match_brace(text, i):
    depth = 0
    for j in range(i, len(text)):
        ch = text[j]
        if ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                return j
    return len(text) - 1


def _first_body_brace(text, pos, stop_semicolon=True):
    """Index of the '{' that opens a body after a header starting at pos, skipping parens/brackets; -1 on ';' first."""
    depth = 0
    j = pos
    n = len(text)
    while j < n:
        ch = text[j]
        if ch in "([":
            depth += 1
        elif ch in ")]":
