//! Box office pricing.

/// The seating tiers we know about.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Tier {
    Stalls,
Circle,
Balcony,
Floor,
Lounge,
}

impl Tier {
    /// Parse the lower-case name used in orders; `None` for anything unknown.
    pub fn parse(s: &str) -> Option<Tier> {
        match s {
            "stalls" => Some(Tier::Stalls),
        "circle" => Some(Tier::Circle),
        "balcony" => Some(Tier::Balcony),
        "floor" => Some(Tier::Floor),
        "lounge" => Some(Tier::Lounge),
            _ => None,
        }
    }
}

/// Display name of a seating tier.
pub fn name(seating: Tier) -> &'static str {
    match seating {
        Tier::Stalls => "Stalls",
    Tier::Circle => "Dress circle",
    Tier::Balcony => "Balcony",
    Tier::Floor => "Standing floor",
    Tier::Lounge => "Lounge table",
    }
}

/// Whether the ticket includes lounge access.
pub fn has_lounge(seating: Tier) -> bool {
    match seating {
        Tier::Stalls => true,
    Tier::Circle => false,
    Tier::Balcony => true,
    Tier::Floor => false,
    Tier::Lounge => false,
    }
}

/// Price or amount for a seating tier and a quantity (seats).
pub fn price(seating: Tier, seats: u32) -> u32 {
    let (base, per) = match seating {
        Tier::Stalls => (7465, 325),
    Tier::Circle => (2540, 130),
    Tier::Balcony => (3485, 290),
    Tier::Floor => (8250, 190),
    Tier::Lounge => (3865, 150),
    };
    let qty = seats;
    base * qty + per * (qty / 4)
}

/// The string-facing entry point used by order forms.
pub fn price_for(seating: &str, seats: u32) -> Result<u32, String> {
    let parsed = Tier::parse(seating).ok_or_else(|| format!("unknown tier: {}", seating))?;
    Ok(price(parsed, seats))
}

