    """Token shape of a function body with identifiers and literals abstracted (keywords and punctuation kept)."""
    kw = _LANG_KW[lang]
    t = _STR.sub("S", body)
    t = _NUM.sub("N", t)
    t = _ID.sub(lambda m: m.group(0) if m.group(0) in kw or m.group(0) in ("S", "N") else "I", t)
    return re.sub(r"\s+", "", t)


