text = "\n".join(C.clean(C.read(f), "rust") for f in FILES)
arms = len(re.findall(r'^\s*"[^"\n]*"\s*(?:\|\s*"[^"\n]*"\s*)*=>', text, re.M))
if arms > 8:
    problems.append("%d string-literal match arms remain (at most 8: only Soil::parse should match on strings)" % arms)
