/// Display name of a soil type.
pub fn describe(soil: &str) -> Result<&'static str, String> {
    match soil {
        "peat" => Ok("Peat"),
    "sand" => Ok("Sandy"),
    "silt" => Ok("Silty"),
    "loam" => Ok("Loam"),
    "chalk" => Ok("Chalky"),
    "clay" => Ok("Heavy clay"),
        _ => Err(format!("unknown soil: {}", soil)),
    }
}

/// Whether the bed needs liming.
pub fn needs_lime(soil: &str) -> Result<bool, String> {
    match soil {
        "peat" => Ok(false),
    "sand" => Ok(true),
    "silt" => Ok(true),
    "loam" => Ok(false),
    "chalk" => Ok(false),
    "clay" => Ok(true),
        _ => Err(format!("unknown soil: {}", soil)),
    }
}

/// Price or amount for a soil type and a quantity (sqm).
pub fn water_litres(soil: &str, sqm: u32) -> Result<u32, String> {
    let base = match soil {
        "peat" => 95,
    "sand" => 105,
    "silt" => 95,
    "loam" => 70,
    "chalk" => 90,
    "clay" => 65,
        _ => return Err(format!("unknown soil: {}", soil)),
    };
    let per = match soil {
        "peat" => 30,
    "sand" => 25,
    "silt" => 20,
    "loam" => 20,
    "chalk" => 20,
    "clay" => 15,
        _ => return Err(format!("unknown soil: {}", soil)),
    };
    let qty = sqm;
    Ok(base + per * qty / 10)
}

