import re

import clike as C

FILES = C.files([".rs"], dirs=["src"])
problems = []
text = "\n".join(C.clean(C.read(f), "rust") for f in FILES)
arms = len(re.findall(r'^\s*"[^"\n]*"\s*(?:\|\s*"[^"\n]*"\s*)*=>', text, re.M))
if arms > 7:
    problems.append("%d string-literal match arms remain (at most 7: only Zone::parse should match on strings)" % arms)
if re.search(r'==\s*"', text):
    problems.append("comparison with a string literal found")
m = re.search(r"\benum\s+Zone\s*\{([^}]*)\}", text)
if not m:
    problems.append("missing enum Zone")
else:
    for v in ["Eu", "World", "Pickup", "Express", "Remote"]:
        if not re.search(r"\b" + v + r"\b", m.group(1)):
            problems.append("enum Zone lacks the variant " + v)
C.report(problems)

