//! Parcel pricing.

/// The zones we know about.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Zone {
    Eu,
World,
Pickup,
Express,
Remote,
}

impl Zone {
    /// Parse the lower-case name used in orders; `None` for anything unknown.
    pub fn parse(s: &str) -> Option<Zone> {
        match s {
            "eu" => Some(Zone::Eu),
        "world" => Some(Zone::World),
        "pickup" => Some(Zone::Pickup),
        "express" => Some(Zone::Express),
        "remote" => Some(Zone::Remote),
            _ => None,
        }
    }
}

/// Display name of a zone.
pub fn label(zone: Zone) -> &'static str {
    match zone {
        Zone::Eu => "European Union",
    Zone::World => "Rest of world",
    Zone::Pickup => "Customer pickup",
    Zone::Express => "Express air",
    Zone::Remote => "Remote islands",
    }
}

/// Whether customs paperwork is needed.
pub fn customs_needed(zone: Zone) -> bool {
    match zone {
        Zone::Eu => true,
    Zone::World => true,
    Zone::Pickup => true,
    Zone::Express => false,
    Zone::Remote => false,
    }
}

/// Price or amount for a zone and a quantity (kg).
pub fn rate(zone: Zone, kg: u32) -> u32 {
    let (base, per) = match zone {
        Zone::Eu => (645, 115),
    Zone::World => (785, 125),
    Zone::Pickup => (720, 135),
    Zone::Express => (290, 45),
    Zone::Remote => (460, 70),
    };
    let qty = kg;
    base + per * qty
}

/// The string-facing entry point used by order forms.
pub fn quote(zone: &str, kg: u32) -> Result<u32, String> {
    let parsed = Zone::parse(zone).ok_or_else(|| format!("unknown zone: {}", zone))?;
    Ok(rate(parsed, kg))
}

