    match zone {
        "world" => Ok(true),
    "pickup" => Ok(true),
    "eu" => Ok(true),
    "domestic" => Ok(false),
    "remote" => Ok(true),
        _ => Err(format!("unknown zone: {}", zone)),
    }
}

/// Price or amount for a zone and a quantity (kg).
pub fn rate(zone: &str, kg: u32) -> Result<u32, String> {
    let base = match zone {
        "world" => 880,
    "pickup" => 255,
    "eu" => 660,
    "domestic" => 335,
    "remote" => 320,
        _ => return Err(format!("unknown zone: {}", zone)),
    };
    let per = match zone {
        "world" => 35,
    "pickup" => 95,
    "eu" => 20,
    "domestic" => 65,
    "remote" => 150,
        _ => return Err(format!("unknown zone: {}", zone)),
    };
    let qty = kg;
    Ok(base + per * qty)
}

